"""Own null false-fire table for EXP-BINSTD-f442a9 (TASK-20261002-b8360c, J3 item (i)).

Written from the FROZEN RULE TEXT of experiments/EXP-BINSTD-f442a9/specification.yaml
and the hypothesis H-BINSTD-0dd2ce only, BEFORE the producer's C-5 table, C-6 output,
decision_rules code, null_calibration code or dry_call code was opened.

Synthetic inputs only. No declared toy cell is constructed: the only cell-specific
inputs are the C-7 DESIGN FIGURES (q, g, l') read from the audit sheet, used as
parameters of an abstract model. No point, trace, cover, divisor or relation of any
declared cell is computed.

Abstract models:
  H1-A  contract idealised null: k ~ Bin(S, p), p = 2^delta / g!
  H1-B  finite population: the samples live in a cyclic group of order l' (C-7);
        k_sub ~ Bin(l', p) split elements, k ~ Bin(S, k_sub / l')
  H2-M2 the contract's own relation-collection PROCEDURE under its own random model
        (H-DL-1 exact; roots of a split u uniform over the |X| ~ q/2 x-coordinates
        carrying a rational point; factor base = first ceil(q^(7/8)) of them;
        union-find large-prime graph; stop at |F| + 10), unrestricted population
  H2-M3 same, random walk confined to the cyclic subgroup of order l' (C-7), duplicates
        removed (a repeated element yields no new relation)
  H2-M4 same as M3 but duplicates counted (a repeated element re-counted)
  H2-M1 the law itself (log2 T = log2 kappa + 1.75 log2 q + replicate noise taken
        from the M2 simulation's own spread) -- the circular null, for comparison
"""
import math, sys, json, random
import numpy as np

Z99 = 2.5758293035489004   # two-sided 99 percent normal quantile
Z95 = 1.959963984540054
G = 8
GFACT = math.factorial(G)          # 40320
LOG2GF = math.log2(GFACT)          # 15.299

def wilson(k, n, z=Z99):
    if n == 0:
        return (0.0, 1.0)
    ph = k / n
    den = 1 + z * z / n
    cen = (ph + z * z / (2 * n)) / den
    half = z * math.sqrt(ph * (1 - ph) / n + z * z / (4 * n * n)) / den
    return (max(0.0, cen - half), min(1.0, cen + half))

def log2s(x):
    return -1e9 if x <= 0 else math.log2(x)

def bits_interval(k, n, ref):
    lo, hi = wilson(k, n)
    return (log2s(lo / ref), log2s(hi / ref))

def outside(iv, a, b):          # STRICT reading: interval entirely outside [a, b]
    return iv[1] < a or iv[0] > b

def not_inside(iv, a, b):       # LOOSE reading: interval not contained in [a, b]
    return iv[0] < a or iv[1] > b

def inside(iv, a, b):
    return iv[0] >= a and iv[1] <= b

# ---------------------------------------------------------------- H-DL-1 laws
def fixed_point_law(g):
    return [sum((-1) ** i / math.factorial(i) for i in range(g - j + 1)) / math.factorial(j)
            for j in range(g + 1)]

def involutions(g):
    I = [1, 1]
    for n in range(2, g + 1):
        I.append(I[n - 1] + (n - 1) * I[n - 2])
    return I[g]

FPL = fixed_point_law(G)
I8 = involutions(G)            # 764
P2S = I8 / GFACT

def dr_h1_bulk(k_cover, k_null, S, reading):
    """DR-H1 from the spec text. reading in {'strict','loose'} for 'lies outside'."""
    ref = 1.0 / GFACT
    ivc = bits_interval(k_cover, S, ref)
    ivn = bits_interval(k_null, S, ref)
    out = outside if reading == 'strict' else not_inside
    if out(ivn, -1.0, 1.0):
        return 'INVALID_NULL'
    if inside(ivc, -0.5, 0.5):
        return 'VALIDATED'
    if out(ivc, -1.0, 1.0):
        return 'FALSIFIED'
    return 'INCONCLUSIVE'

def dr_h1_tail(hist, S, k2, reading):
    tv = 0.5 * sum(abs(hist[j] / S - FPL[j]) for j in range(G + 1))
    iv2 = bits_interval(k2, S, P2S)
    out = outside if reading == 'strict' else not_inside
    if tv <= 0.02 and inside(iv2, -0.5, 0.5):
        return 'TAIL_PASS'
    if tv > 0.05 or out(iv2, -1.0, 1.0):
        return 'TAIL_FAIL'
    return 'TAIL_INCONCLUSIVE'

def h1_outcome(admit, bulk, tail):
    # my reading of the spec (combination rule is not spelled out in the spec text)
    if not admit:
        return 'NOT_ADMITTED'
    if bulk == 'INVALID_NULL':
        return 'INVALID_NULL'
    if bulk == 'FALSIFIED' or tail == 'TAIL_FAIL':
        return 'FALSIFIED'
    if bulk == 'VALIDATED' and tail == 'TAIL_PASS':
        return 'VALIDATED'
    return 'INCONCLUSIVE'

def sim_h1(rng, n_runs, S, delta_bits, lprime, reading, null_sd_bits=0.0):
    """Returns outcome counts of DR-H1 bulk, tail and combined over n_runs."""
    p = (2.0 ** delta_bits) / GFACT
    counts = {}
    for _ in range(n_runs):
        if lprime is None:
            k = rng.binomial(S, p)
            hist = rng.multinomial(S, FPL)
            k2 = rng.binomial(S, P2S)
        else:
            ksub = rng.binomial(lprime, p)
            k = rng.binomial(S, ksub / lprime)
            hsub = rng.multinomial(lprime, FPL)
            hist = rng.multinomial(S, hsub / lprime)
            k2sub = rng.binomial(lprime, P2S)
            k2 = rng.binomial(S, k2sub / lprime)
        pn = (2.0 ** (rng.normal(0.0, null_sd_bits) if null_sd_bits > 0 else 0.0)) / GFACT
        kn = rng.binomial(S, min(pn, 1.0))
        b = dr_h1_bulk(k, kn, S, reading)
        t = dr_h1_tail(hist, S, k2, reading)
        o = h1_outcome(True, b, t)
        for key in ('bulk:' + b, 'tail:' + t, 'h1:' + o):
            counts[key] = counts.get(key, 0) + 1
    return counts

# ---------------------------------------------------------------- H-DL-2 procedure model
class UF:
    __slots__ = ('p',)
    def __init__(self):
        self.p = {}
    def find(self, a):
        p = self.p
        if a not in p:
            p[a] = a
            return a
        r = a
        while p[r] != r:
            r = p[r]
        while p[a] != r:
            p[a], a = r, p[a]
        return r
    def union(self, a, b):
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            return False
        self.p[ra] = rb
        return True

def split_root_sets(rng, n, X):
    """n split elements: g distinct roots uniform over X x-coordinates (indices 0..X-1).
    Vectorised rejection sampling: rows with a repeated root are redrawn."""
    out = np.sort(rng.integers(0, X, size=(n, G)), axis=1)
    bad = np.any(out[:, 1:] == out[:, :-1], axis=1)
    while bad.any():
        nb = int(bad.sum())
        out[bad] = np.sort(rng.integers(0, X, size=(nb, G)), axis=1)
        bad = np.any(out[:, 1:] == out[:, :-1], axis=1)
    return out

def classify(roots, f):
    lp = roots[roots >= f]
    return lp

def collect(rng, q, X, f, need, cap, lprime=None, dedup=True, max_events=None):
    """Return (trials, censored, n_split_events, n_distinct_used)."""
    p_split = 1.0 / GFACT
    uf = UF()
    full = 0
    cycles = 0
    SPECIAL = -1
    if lprime is None:
        # unrestricted: every split event is a fresh uniform split element
        n_ev = 0
        batch = 256
        while full + cycles < need:
            rs = split_root_sets(rng, batch, X)
            for r in rs:
                n_ev += 1
                lp = r[r >= f]
                if len(lp) == 0:
                    full += 1
                elif len(lp) == 1:
                    if not uf.union(int(lp[0]), SPECIAL):
                        cycles += 1
                elif len(lp) == 2:
                    if not uf.union(int(lp[0]), int(lp[1])):
                        cycles += 1
                if full + cycles >= need:
                    break
            if max_events and n_ev > max_events:
                break
        trials = n_ev + int(rng.negative_binomial(n_ev, p_split)) if n_ev > 0 else 0
        cens = trials > cap
        return (min(trials, cap), cens, n_ev, n_ev)
    # restricted to a cyclic group of order lprime: K_sub split elements with fixed roots
    ksub = int(rng.binomial(lprime, p_split))
    if ksub == 0:
        return (cap, True, 0, 0)
    pool = split_root_sets(rng, ksub, X)
    # classify pool
    kinds = []
    for r in pool:
        lp = r[r >= f]
        kinds.append(tuple(int(v) for v in lp) if len(lp) <= 2 else None)
    rate = ksub / lprime            # probability a trial hits a split element
    seen = set()
    trials = 0
    n_ev = 0
    n_dist = 0
    while full + cycles < need:
        gap = int(rng.geometric(rate))
        trials += gap
        if trials > cap:
            return (cap, True, n_ev, n_dist)
        n_ev += 1
        idx = int(rng.integers(ksub))
        if dedup:
            if idx in seen:
                # quick exhaustion test: if every split element seen, stop as censored
                if len(seen) == ksub:
                    return (cap, True, n_ev, n_dist)
                continue
            seen.add(idx)
        n_dist = len(seen)
        kd = kinds[idx]
        if kd is None:
            continue
        if len(kd) == 0:
            full += 1
        elif len(kd) == 1:
            if not uf.union(kd[0], SPECIAL):
                cycles += 1
        else:
            if not uf.union(kd[0], kd[1]):
                cycles += 1
    return (trials, False, n_ev, n_dist)

def max_relations_in_pool(rng, lprime, X, f):
    """Upper bound on distinct relations the whole subgroup can give (all split elements used)."""
    ksub = int(rng.binomial(lprime, 1.0 / GFACT))
    pool = split_root_sets(rng, ksub, X)
    uf = UF(); full = 0; cyc = 0
    for r in pool:
        lp = r[r >= f]
        if len(lp) == 0:
            full += 1
        elif len(lp) == 1:
            if not uf.union(int(lp[0]), -1):
                cyc += 1
        elif len(lp) == 2:
            if not uf.union(int(lp[0]), int(lp[1])):
                cyc += 1
    return ksub, full, cyc

def dr_h2(points):
    """points: list of (log2q, log2T, censored). From the spec/hypothesis text."""
    if len(points) < 3:
        return 'INVALID_INSUFFICIENT', None, None
    xs = [p[0] for p in points]; ys = [p[1] for p in points]
    xm = sum(xs) / 3; ym = sum(ys) / 3
    sxx = sum((x - xm) ** 2 for x in xs)
    sxy = sum((x - xm) * (y - ym) for x, y in zip(xs, ys))
    slope = sxy / sxx
    kap = [y - 1.75 * x for x, y in zip(xs, ys)]
    if any(p[2] for p in points) or abs(slope - 1.75) > 0.5 or any(k < -2 or k > LOG2GF + 1 for k in kap):
        return 'FALSIFIED', slope, kap
    if abs(slope - 1.75) <= 0.25 and all(-0.5 <= k <= LOG2GF + 0.5 for k in kap):
        return 'VALIDATED', slope, kap
    return 'INCONCLUSIVE', slope, kap

H2_LANES = [  # (name, log2 q, l' from C-7 design figures)
    ('TC-C', 10, 40023041),
    ('TC-E', 11, 14868569),
    ('TC-F', 13, 3972759389),
]

def run_h2(rng, model, n_runs, X_extra=0):
    outs = {}
    slopes = []
    kaps = {n: [] for n, _, _ in H2_LANES}
    cens_ct = {n: 0 for n, _, _ in H2_LANES}
    for _ in range(n_runs):
        pts = []
        for name, lq, lp in H2_LANES:
            q = 2 ** lq
            X = q // 2 + X_extra
            f = math.ceil(q ** (7 / 8))
            need = f + 10
            cap = int(2 * GFACT * q ** 1.75)
            reps = []
            cens = False
            for _r in range(3):
                if model == 'M2':
                    t, c, _, _ = collect(rng, q, X, f, need, cap, None)
                elif model == 'M3':
                    t, c, _, _ = collect(rng, q, X, f, need, cap, lp, dedup=True)
                elif model == 'M4':
                    t, c, _, _ = collect(rng, q, X, f, need, cap, lp, dedup=False)
                reps.append(math.log2(t)); cens = cens or c
            if cens:
                cens_ct[name] += 1
            pts.append((lq, sum(reps) / 3, cens))
        o, s, k = dr_h2(pts)
        outs[o] = outs.get(o, 0) + 1
        if s is not None:
            slopes.append(s)
            for (name, _, _), kv in zip(H2_LANES, k):
                kaps[name].append(kv)
    return outs, slopes, kaps, cens_ct

def summarize(v):
    a = np.array(v)
    return {'mean': round(float(a.mean()), 4), 'sd': round(float(a.std(ddof=1)), 4) if len(a) > 1 else None,
            'min': round(float(a.min()), 4), 'max': round(float(a.max()), 4)}

def main():
    which = sys.argv[1]
    seed = int(sys.argv[2])
    n = int(sys.argv[3])
    rng = np.random.default_rng(seed)
    res = {'which': which, 'seed': seed, 'n_runs': n, 'numpy': np.__version__, 'python': sys.version.split()[0]}
    if which == 'h1':
        S = 2 ** 24
        table = {}
        for reading in ('strict', 'loose'):
            for label, delta, lp, nsd in [
                ('A_exact_r0', 0.0, None, 0.0),
                ('A_edge_+0.5', 0.5, None, 0.0),
                ('A_edge_-0.5', -0.5, None, 0.0),
                ('B_TC-C_lprime_r0', 0.0, 40023041, 0.0),
                ('B_TC-E_lprime_r0', 0.0, 14868569, 0.0),
                ('B_TC-F_lprime_r0', 0.0, 3972759389, 0.0),
                ('B_TC-E_lprime_edge_-0.5', -0.5, 14868569, 0.0),
                ('B_TC-E_lprime_edge_+0.5', 0.5, 14868569, 0.0),
                ('A_r0_realnull_q2^10_sd0.316', 0.0, None, 0.316),
            ]:
                table[reading + '|' + label] = sim_h1(rng, n, S, delta, lp, reading, nsd)
        res['h1'] = table
    elif which == 'h2':
        model = sys.argv[4]
        outs, slopes, kaps, cens = run_h2(rng, model, n)
        res['model'] = model
        res['h2_outcomes'] = outs
        res['slope'] = summarize(slopes) if slopes else None
        res['log2_kappa'] = {k: summarize(v) for k, v in kaps.items() if v}
        res['censored_points'] = cens
    elif which == 'pool':
        out = {}
        for name, lq, lp in H2_LANES:
            q = 2 ** lq; X = q // 2; f = math.ceil(q ** (7 / 8))
            vals = [max_relations_in_pool(rng, lp, X, f) for _ in range(n)]
            out[name] = {'need': f + 10, 'X': X, 'f': f, 'lprime': lp,
                         'ksub': summarize([v[0] for v in vals]),
                         'full': summarize([v[1] for v in vals]),
                         'cycles': summarize([v[2] for v in vals]),
                         'max_relations': summarize([v[1] + v[2] for v in vals]),
                         'runs_with_max_below_need': sum(1 for v in vals if v[1] + v[2] < f + 10)}
        res['pool'] = out
    print(json.dumps(res, indent=1, sort_keys=True))

if __name__ == '__main__':
    main()

toy_d3_trace.py.text:
"""Non-declared toy group check of the (C1) trace-eigenvalue core (L4) and its inapplicability
on an open lane (L6), and the committed decision path for the resulting counts.

Group: E: y^2 + xy = x^3 + b over F_8 (d = 3, NEVER a declared d; F_8 meets F_4, F_16, F_256 only
in F_2, and no declared toy curve or deployed row is definable over F_2^15), attacked over
K = F_2^15 (k' = 5). Collapsed analogue c = 1: period p = 3, n = 15, k = 5, Tr = sum_{r<5} pi^r with
pi the 2^3-power Frobenius. Open analogue c = 5: n = 3, period 3 = n, k = 1, 'Tr' = identity.
No cover and no GHS map is built (that would be an executor instrument); this checks only the
algebra of L4/L6 on points, and feeds the counts to the committed decision code.
"""
import random, sys, json, hashlib, importlib.util

MOD = (1 << 15) | (1 << 1) | 1   # x^15 + x + 1
N = 15

def gmul(a, b):
    r = 0
    while b:
        if b & 1:
            r ^= a
        b >>= 1
        a <<= 1
        if a >> N:
            a ^= MOD
    return r

def gpow(a, e):
    r = 1
    while e:
        if e & 1:
            r = gmul(r, a)
        a = gmul(a, a)
        e >>= 1
    return r

def ginv(a):
    return gpow(a, (1 << N) - 2)

def is_irreducible():
    # x^(2^15) == x mod MOD and gcd(x^(2^i) - x, MOD) == 1 for i in {3, 5}
    def xpow2(i):
        a = 2
        for _ in range(i):
            a = gmul(a, a)
        return a
    def pgcd(a, b):
        while b:
            # polynomial mod
            while a and a.bit_length() >= b.bit_length():
                a ^= b << (a.bit_length() - b.bit_length())
            a, b = b, a
        return a
    if xpow2(15) != 2:
        return False
    for i in (3, 5):
        if pgcd(MOD, xpow2(i) ^ 2) != 1:
            return False
    return True

assert is_irreducible()
# F_8 inside F_2^15: elements fixed by z -> z^8
gen = None
for g in range(2, 1 << N):
    if gpow(g, ((1 << N) - 1) // 7) != 1:
        gen = gpow(g, ((1 << N) - 1) // 7)   # element of order 7, generates F_8
        break
F8 = sorted({0, 1} | {gpow(gen, i) for i in range(7)})
assert all(gpow(z, 8) == z for z in F8) and len(F8) == 8
b = gen  # b in F_8 \ F_2

def on_curve(P):
    if P is None:
        return True
    x, y = P
    return gmul(y, y) ^ gmul(x, y) == gmul(gmul(x, x), x) ^ b

def add(P, Q):
    if P is None:
        return Q
    if Q is None:
        return P
    x1, y1 = P; x2, y2 = Q
    if x1 == x2:
        if y2 == x1 ^ y1:          # Q = -P, with -(x, y) = (x, x + y); covers 2-torsion x = 0
            return None
        # here y1 == y2 and x1 != 0: doubling, a = 0
        lam = x1 ^ gmul(y1, ginv(x1))
        x3 = gmul(lam, lam) ^ lam
        y3 = gmul(x1, x1) ^ gmul(lam ^ 1, x3)
        return (x3, y3)
    lam = gmul(y1 ^ y2, ginv(x1 ^ x2))
    x3 = gmul(lam, lam) ^ lam ^ x1 ^ x2
    y3 = gmul(lam, x1 ^ x3) ^ x3 ^ y1
    return (x3, y3)

def mul(k, P):
    R = None
    while k:
        if k & 1:
            R = add(R, P)
        P = add(P, P)
        k >>= 1
    return R

def frob(P, e):  # 2^e-power Frobenius on coordinates
    if P is None:
        return None
    x, y = P
    for _ in range(e):
        x = gmul(x, x); y = gmul(y, y)
    return (x, y)

# #E(F_8) by enumeration (F_8 inside F_2^15)
def count_small():
    c = 1
    for x in F8:
        for y in F8:
            if on_curve((x, y)):
                c += 1
    return c

h = count_small()
t = 8 + 1 - h
# Weil recursion to #E(F_8^5) = #E(F_2^15)
s = [2, t]
for i in range(2, 6):
    s.append(t * s[-1] - 8 * s[-2])
NK = 8 ** 5 + 1 - s[5]

def factor(n):
    f, p = [], 2
    while p * p <= n:
        while n % p == 0:
            f.append(p); n //= p
        p += 1
    if n > 1:
        f.append(n)
    return f

L = NK // h
lp = max(factor(L))
rng = random.Random(20261112)

def random_point():
    while True:
        x = rng.randrange(1, 1 << N)
        # solve y^2 + x y = x^3 + b: z^2 + z = (x^3 + b)/x^2 with y = x z; half-trace (N odd)
        c = gmul(gmul(gmul(x, x), x) ^ b, ginv(gmul(x, x)))
        tr = 0; a = c
        for _ in range(N):
            tr ^= a; a = gmul(a, a)
        if tr != 0:
            continue
        z = 0; a = c
        for i in range(0, N, 2):
            z ^= a
            a = gpow(a, 4)
        if gmul(z, z) ^ z != c:
            continue
        P = (x, gmul(x, z))
        assert on_curve(P)
        return P

pts = []
while len(pts) < 64:
    R = random_point()
    P = mul(NK // lp, R)
    if P is not None:
        assert mul(lp, P) is None
        pts.append(P)

def trace_k(P, k, e):   # sum_{r<k} pi^r(P), pi = 2^e-power Frobenius
    T = None
    Q = P
    for _ in range(k):
        T = add(T, Q)
        Q = frob(Q, e)
    return T

collapsed_nonzero = sum(1 for P in pts if trace_k(P, 5, 3) is not None)
open_nonzero = sum(1 for P in pts if trace_k(P, 1, 15) is not None)
# eigenvalue form: pi acts by lambda with lambda^5 = 1, lambda != 1 mod l'
P0 = pts[0]
piP = frob(P0, 3)
lam = None
for cand in range(2, lp):
    if pow(cand, 5, lp) == 1:
        if mul(cand, P0) == piP:
            lam = cand
            break
S_DIR = sys.argv[1]
spec = importlib.util.spec_from_file_location('dr', S_DIR + '/blocks/decision_rules.py')
dr = importlib.util.module_from_spec(spec); spec.loader.exec_module(dr)
out = {
    'field': 'F_2^15 = F_2[x]/(x^15 + x + 1) (irreducibility checked)', 'b_in_F8': hex(b),
    'h=#E(F_8)': h, 'trace_t': t, '#E(F_2^15)': NK, 'L': L, 'L_factors': factor(L), "l'": lp,
    "gcd(l',h)": __import__('math').gcd(lp, h),
    'samples': len(pts),
    'collapsed_analogue_c=1_trace_nonzero_count': collapsed_nonzero,
    'open_analogue_c=5_identity_nonzero_count': open_nonzero,
    'lambda_with_lambda^5=1_and_lambda!=1': lam,
    'sum_lambda^r_r<5_mod_l': (sum(pow(lam, r, lp) for r in range(5)) % lp) if lam else None,
    'committed_c1_positive(64, open_nonzero)': dr.c1_positive(64, open_nonzero),
    'committed_c1_positive(64, 0)': dr.c1_positive(64, 0),
    'committed_c1_negative(64, collapsed_nonzero, PASS, CONTROL_PASS)': dr.c1_negative(64, collapsed_nonzero, 'PASS', 'CONTROL_PASS'),
}
print(json.dumps(out, indent=1))

