"""Minimal PDF text extractor (stdlib only: re + zlib). Decompresses FlateDecode streams,
interprets Tj / TJ / ' / " text operators and Td/TD/T*/Tm line moves, and prints text.
Used only to read Hess 2003/2004 at source for the Hess obligation (DC-H1, OB-1)."""
import re, sys, zlib

def streams(data):
    out = []
    for m in re.finditer(rb'(\d+)\s+(\d+)\s+obj(.*?)endobj', data, re.S):
        body = m.group(3)
        sm = re.search(rb'stream\r?\n', body)
        if not sm:
            continue
        dic = body[:sm.start()]
        raw = body[sm.end():]
        end = raw.rfind(b'endstream')
        raw = raw[:end]
        if b'FlateDecode' in dic:
            try:
                raw = zlib.decompress(raw)
            except Exception:
                try:
                    raw = zlib.decompressobj().decompress(raw)
                except Exception:
                    continue
        out.append((int(m.group(1)), dic, raw))
    return out

def unescape(s):
    res = bytearray()
    i = 0
    while i < len(s):
        c = s[i]
        if c == 0x5c and i + 1 < len(s):
            n = s[i + 1]
            if n in b'nrtbf':
                res += {ord('n'): b'\n', ord('r'): b'\r', ord('t'): b'\t', ord('b'): b'\b', ord('f'): b'\f'}[n]
                i += 2
            elif 0x30 <= n <= 0x37:
                j = i + 1
                k = j
                while k < len(s) and k < j + 3 and 0x30 <= s[k] <= 0x37:
                    k += 1
                res.append(int(s[j:k], 8) & 0xff)
                i = k
            else:
                res.append(n)
                i += 2
        else:
            res.append(c)
            i += 1
    return bytes(res)

TOK = re.compile(rb'\((?:\\.|[^\\)])*\)|\[|\]|<[0-9A-Fa-f\s]*>|/[^\s/\[\]()<>]+|[-+]?\d*\.?\d+|[A-Za-z\'"*]+', re.S)

def text_of(content):
    out = []
    arr = None
    stack = []
    line = []
    def flush():
        if line:
            out.append(''.join(line))
            line.clear()
    for m in TOK.finditer(content):
        t = m.group(0)
        if t == b'[':
            arr = []
            continue
        if t == b']':
            stack.append(arr)
            arr = None
            continue
        if arr is not None:
            if t.startswith(b'('):
                arr.append(unescape(t[1:-1]).decode('latin-1'))
            else:
                try:
                    v = float(t)
                    if v < -250:
                        arr.append(' ')
                except ValueError:
                    pass
            continue
        if t.startswith(b'('):
            stack.append(unescape(t[1:-1]).decode('latin-1'))
            continue
        if t in (b'Tj', b"'", b'"'):
            if stack and isinstance(stack[-1], str):
                if t != b'Tj':
                    flush()
                line.append(stack[-1])
            stack.clear()
        elif t == b'TJ':
            if stack and isinstance(stack[-1], list):
                line.append(''.join(stack[-1]))
            stack.clear()
        elif t in (b'Td', b'TD', b'T*', b'Tm', b'ET'):
            if t in (b'Td', b'TD'):
                # a vertical move starts a new line; small horizontal moves add a space
                nums = [s for s in stack if isinstance(s, bytes)]
                flush() if True else None
            else:
                flush()
            stack.clear()
        else:
            try:
                stack.append(t if not t[:1].isalpha() else t)
            except Exception:
                pass
            if len(stack) > 50:
                stack = stack[-50:]
    flush()
    return '\n'.join(out)

def main():
    data = open(sys.argv[1], 'rb').read()
    ss = streams(data)
    pages = []
    for num, dic, raw in ss:
        if b'/Length' in dic and (b'BT' in raw and (b'Tj' in raw or b'TJ' in raw)):
            pages.append((num, text_of(raw)))
    for num, txt in pages:
        print(f'=== stream obj {num} ===')
        print(txt)

if __name__ == '__main__':
    main()

